<?php
declare(strict_types=1);
final class OperationsService {
    public static function distribute(int $documentId,array $recipients): int {RbacService::authorize('documents.distribute');$d=DocumentService::find($documentId);if(!in_array($d['status'],['signed','distributed'],true))throw new RuntimeException('Dokumen harus ditandatangani.',409);$u=AuthService::requireUser();return Database::transaction(function(PDO $db)use($documentId,$recipients,$u,$d){$db->prepare("INSERT INTO distributions(document_id,distributed_by,channel) VALUES(?,?,'in_app')")->execute([$documentId,$u['id']]);$id=(int)$db->lastInsertId();foreach($recipients as $r){$db->prepare('INSERT INTO distribution_recipients(distribution_id,recipient_type,recipient_reference_id,external_name,external_email,recipient_role,delivery_status,sent_at) VALUES(?,?,?,?,?,?,"sent",NOW())')->execute([$id,$r['type'],$r['id']??null,$r['name']??null,$r['email']??null,$r['role']??'recipient']);if(($r['type']??'')==='user'&&!empty($r['id']))NotificationService::send((int)$r['id'],'distribution-'.$id.'-'.$r['id'],'distribution','Surat baru diterima',$d['title'],'document',$documentId,'?page=document-detail&id='.$documentId);}$db->prepare('UPDATE documents SET status="distributed",distributed_at=NOW() WHERE id=?')->execute([$documentId]);self::createAgendas($db,$documentId);AuditService::log('document.distributed','document',$documentId,null,['recipients'=>count($recipients)]);return $id;});}
    private static function createAgendas(PDO $db,int $documentId):void{$q=$db->prepare('SELECT da.id,u.id user_id,d.title,d.effective_from,d.effective_until FROM document_assignees da JOIN employees e ON e.id=da.employee_id JOIN users u ON u.employee_id=e.id JOIN documents d ON d.id=da.document_id WHERE da.document_id=?');$q->execute([$documentId]);foreach($q as $a)$db->prepare('INSERT INTO agendas(document_id,document_assignee_id,owner_user_id,title,starts_at,ends_at) VALUES(?,?,?,?,?,?)')->execute([$documentId,$a['id'],$a['user_id'],$a['title'],($a['effective_from']?:date('Y-m-d')).' 08:00:00',($a['effective_until']?:$a['effective_from']?:date('Y-m-d')).' 16:00:00']);}
    public static function disposition(int $documentId,array $data):int{RbacService::authorize('dispositions.manage');$u=AuthService::requireUser();$q=Database::connection()->prepare('INSERT INTO dispositions(document_id,parent_id,created_by,assignee_type,assignee_reference_id,instruction,priority,due_at) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$documentId,$data['parent_id']??null,$u['id'],$data['assignee_type'],$data['assignee_reference_id'],$data['instruction'],$data['priority']??'normal',$data['due_at']??null]);$id=(int)Database::connection()->lastInsertId();AuditService::log('disposition.created','disposition',$id);return $id;}
    public static function report(int $documentId,array $data):int{RbacService::authorize('reports.create');$u=AuthService::requireUser();$q=Database::connection()->prepare('INSERT INTO execution_reports(document_id,document_assignee_id,report_type,author_user_id,status,actual_started_at,actual_ended_at,actual_location,summary,results,constraints_text,conclusion,recommendations,content_json,due_at) VALUES(?,?,?,? ,"draft",?,?,?,?,?,?,?,?,?,?)');$q->execute([$documentId,$data['document_assignee_id']??null,$data['report_type']??'individual',$u['id'],$data['actual_started_at']??null,$data['actual_ended_at']??null,$data['actual_location']??null,$data['summary']??null,$data['results']??null,$data['constraints']??null,$data['conclusion']??null,$data['recommendations']??null,json_encode($data),$data['due_at']??null]);$id=(int)Database::connection()->lastInsertId();AuditService::log('report.created','execution_report',$id);return $id;}
}
